// ================================================================
// LAYER 3 - NODE 3-1: 데이터 정제/정규화 (BUG FIX v2.0)
// FIX #1: fifty_two_week_high → fiftyTwoWeekHigh (price not percentage)
// ================================================================

const inputs = $input.all();
const yahoo = inputs[0]?.json || {};
const alpha = inputs[1]?.json || {};

const fin = yahoo.quoteSummary?.result?.[0];
const fd = fin?.financialData;
const ks = fin?.defaultKeyStatistics;
const is = fin?.incomeStatementHistory?.incomeStatementHistory?.[0];
const bs = fin?.balanceSheetHistory?.balanceSheetHistory?.[0];
const cf = fin?.cashflowStatementHistory?.cashflowStatements?.[0];

const safe = (obj, key, fallback = null) => {
  const val = obj?.[key]?.raw;
  return (val !== undefined && val !== null) ? val : fallback;
};

return [{
  json: {
    // === 메타 ===
    ticker: alpha.Symbol || $('Webhook Trigger').item?.json?.ticker,
    company_name: alpha.Name,
    // FIX #11/#12: Sector 정규화 (Alpha Vantage 원본 값 보존)
    sector: alpha.Sector || null,
    sector_normalized: (alpha.Sector || '').trim(),
    industry: alpha.Industry,
    market_cap: safe(fd, 'marketCap'),
    currency: fd?.financialCurrency || 'USD',

    // === 가격 데이터 ===
    current_price: safe(fd, 'currentPrice'),
    target_price_analyst: safe(fd, 'targetMeanPrice'),
    // FIX #1: 52WeekChange(비율)이 아닌 실제 52주 최고/최저가로 수정
    fifty_two_week_high: safe(ks, 'fiftyTwoWeekHigh'),
    fifty_two_week_low: safe(ks, 'fiftyTwoWeekLow'),
    week_52_change_pct: safe(ks, '52WeekChange'),  // 퍼센트 변화율 (별도 보관)
    beta: safe(ks, 'beta'),

    // === 손익계산서 ===
    revenue: safe(is, 'totalRevenue'),
    gross_profit: safe(is, 'grossProfit'),
    ebit: safe(is, 'ebit'),
    net_income: safe(is, 'netIncome'),
    eps: safe(ks, 'trailingEps'),
    eps_forward: safe(ks, 'forwardEps'),

    // === 재무상태표 ===
    total_assets: safe(bs, 'totalAssets'),
    total_equity: safe(bs, 'totalStockholderEquity'),
    total_debt: safe(bs, 'longTermDebt'),
    book_value_per_share: safe(ks, 'bookValue'),
    shares_outstanding: safe(ks, 'sharesOutstanding'),  // FIX #10: 직접 주식수 사용

    // === 현금흐름 ===
    operating_cash_flow: safe(cf, 'totalCashFromOperatingActivities'),
    capex: safe(cf, 'capitalExpenditures'),
    free_cash_flow: safe(fd, 'freeCashflow'),

    // === 성장률 ===
    revenue_growth: safe(fd, 'revenueGrowth'),
    earnings_growth: safe(fd, 'earningsGrowth'),

    // === 수익성 ===
    roe: safe(fd, 'returnOnEquity'),
    roa: safe(fd, 'returnOnAssets'),
    profit_margin: safe(fd, 'profitMargins'),
    operating_margin: safe(fd, 'operatingMargins'),

    collected_at: new Date().toISOString(),
    data_quality_score: null
  }
}];

// ================================================================
// LAYER 3 - NODE 3-2: PER/PBR/DCF 계산 (BUG FIX v2.0)
// FIX #2: DCF Phase2 이중 복리 버그 수정
// FIX #3: 터미널 밸류 오프-바이-원 수정
// FIX #6: 할인율 ≤ 성장률 제로 나눗셈 방어
// FIX #7: 음수 EPS PER 역전 방지
// FIX #8: 음수 장부가 PBR 방지
// FIX #9: 음수 FCF 루프 방어
// FIX #10: current_price=0 무한대 방지
// FIX #11: 누락 섹터 벤치마크 추가
// FIX #12: 섹터 이름 대소문자 정규화
// FIX #17: 베타 연동 안전마진 동적 조정
// FIX #18: 가중 데이터 품질 점수
// FIX #19: current_price=0 upside 무한대 방지
// ================================================================

const d = $input.first().json;

const pct = (v) => v != null ? (v * 100).toFixed(2) + '%' : 'N/A';
const fmt = (v) => v != null ? v.toLocaleString() : 'N/A';
const ratio = (a, b) => (a != null && b != null && b !== 0) ? (a / b) : null;

// ================================================================
// FIX #11: 누락 섹터 전체 추가
// FIX #12: 섹터 정규화 함수
// ================================================================
const SECTOR_PER_BENCHMARKS = {
  'Technology': { fair: 25, overvalued: 35, undervalued: 15 },
  'Information Technology': { fair: 25, overvalued: 35, undervalued: 15 },
  'Finance': { fair: 12, overvalued: 18, undervalued: 8 },
  'Financial Services': { fair: 12, overvalued: 18, undervalued: 8 },
  'Healthcare': { fair: 20, overvalued: 30, undervalued: 12 },
  'Consumer Cyclical': { fair: 18, overvalued: 28, undervalued: 10 },
  'Consumer Discretionary': { fair: 18, overvalued: 28, undervalued: 10 },
  'Consumer Defensive': { fair: 16, overvalued: 24, undervalued: 10 },
  'Consumer Staples': { fair: 16, overvalued: 24, undervalued: 10 },
  'Energy': { fair: 10, overvalued: 16, undervalued: 6 },
  'Industrials': { fair: 16, overvalued: 24, undervalued: 10 },
  'Materials': { fair: 14, overvalued: 22, undervalued: 8 },
  'Basic Materials': { fair: 14, overvalued: 22, undervalued: 8 },
  'Real Estate': { fair: 14, overvalued: 20, undervalued: 8 },
  'Utilities': { fair: 12, overvalued: 18, undervalued: 8 },
  'Communication Services': { fair: 18, overvalued: 28, undervalued: 10 },
  'default': { fair: 18, overvalued: 25, undervalued: 10 }
};

const SECTOR_PBR_BENCHMARKS = {
  'Technology': { fair: 5, overvalued: 10, undervalued: 2 },
  'Information Technology': { fair: 5, overvalued: 10, undervalued: 2 },
  'Finance': { fair: 1.2, overvalued: 2, undervalued: 0.7 },
  'Financial Services': { fair: 1.2, overvalued: 2, undervalued: 0.7 },
  'Healthcare': { fair: 4, overvalued: 8, undervalued: 2 },
  'Consumer Cyclical': { fair: 3, overvalued: 6, undervalued: 1 },
  'Consumer Discretionary': { fair: 3, overvalued: 6, undervalued: 1 },
  'Consumer Defensive': { fair: 2.5, overvalued: 5, undervalued: 1 },
  'Consumer Staples': { fair: 2.5, overvalued: 5, undervalued: 1 },
  'Energy': { fair: 1.5, overvalued: 3, undervalued: 0.6 },
  'Industrials': { fair: 2.5, overvalued: 5, undervalued: 1 },
  'Materials': { fair: 2, overvalued: 4, undervalued: 0.8 },
  'Basic Materials': { fair: 2, overvalued: 4, undervalued: 0.8 },
  'Real Estate': { fair: 1, overvalued: 2, undervalued: 0.5 },
  'Utilities': { fair: 1.5, overvalued: 2.5, undervalued: 0.8 },
  'Communication Services': { fair: 3, overvalued: 6, undervalued: 1 },
  'default': { fair: 2, overvalued: 4, undervalued: 0.8 }
};

// FIX #12: 대소문자 정규화 후 섹터 벤치마크 조회
const findBenchmark = (table, sector) => {
  if (!sector) return table['default'];
  const normalized = sector.trim();
  const exactMatch = table[normalized];
  if (exactMatch) return exactMatch;
  const caseMatch = Object.keys(table).find(k => k.toLowerCase() === normalized.toLowerCase());
  return caseMatch ? table[caseMatch] : table['default'];
};

const per_bench = findBenchmark(SECTOR_PER_BENCHMARKS, d.sector_normalized);
const pbr_bench = findBenchmark(SECTOR_PBR_BENCHMARKS, d.sector_normalized);

// ================================================================
// [RULE-01] PER 분석
// FIX #7: 음수 EPS는 PER 제외
// ================================================================
const per_trailing = (d.eps && d.eps > 0) ? ratio(d.current_price, d.eps) : null;
const per_forward = (d.eps_forward && d.eps_forward > 0) ? ratio(d.current_price, d.eps_forward) : null;

const per_signal = per_trailing
  ? (per_trailing < per_bench.undervalued ? 'UNDERVALUED'
     : per_trailing > per_bench.overvalued ? 'OVERVALUED' : 'FAIR')
  : 'INSUFFICIENT_DATA';

const per_fair_price = (d.eps && d.eps > 0) ? d.eps * per_bench.fair : null;

// ================================================================
// [RULE-02] PBR 분석
// FIX #8: 음수 장부가(자본잠식) PBR 제외
// ================================================================
const pbr = (d.book_value_per_share && d.book_value_per_share > 0)
  ? ratio(d.current_price, d.book_value_per_share)
  : null;

const pbr_signal = pbr
  ? (pbr < pbr_bench.undervalued ? 'UNDERVALUED'
     : pbr > pbr_bench.overvalued ? 'OVERVALUED' : 'FAIR')
  : 'INSUFFICIENT_DATA';

const pbr_fair_price = (d.book_value_per_share && d.book_value_per_share > 0)
  ? d.book_value_per_share * pbr_bench.fair
  : null;

// ================================================================
// [RULE-03] DCF 모델
// FIX #2: Phase2 이중 복리 버그 - 루프 변수 분리
// FIX #3: 터미널 밸류 오프-바이-원 수정
// FIX #6: DISCOUNT_RATE ≤ GROWTH_RATE_PHASE2 방어
// FIX #9: 음수 FCF 중간 경로 방어
// FIX #10: current_price=0 division by zero 방어
// FIX #17: 베타 연동 안전마진 동적 조정
// ================================================================
const FCF = d.free_cash_flow;
const GROWTH_RATE_PHASE1 = Math.min(
  (d.earnings_growth != null && d.earnings_growth > 0) ? d.earnings_growth : 0.10,
  0.25
);
const GROWTH_RATE_PHASE2 = 0.03;
const DISCOUNT_RATE = 0.10;
const PROJECTION_YEARS = 10;

// FIX #10: 직접 주식수 우선, 없으면 시총/주가 (0 나눗셈 방어)
const SHARES_OUTSTANDING = d.shares_outstanding
  ? d.shares_outstanding
  : (d.market_cap && d.current_price && d.current_price > 0)
    ? d.market_cap / d.current_price
    : null;

let dcf_intrinsic_value = null;
let dcf_signal = 'INSUFFICIENT_DATA';

// FIX #6: 터미널 밸류 제로 나눗셈 방어
if (DISCOUNT_RATE <= GROWTH_RATE_PHASE2) {
  dcf_signal = 'INVALID_PARAMETERS';
} else if (FCF && SHARES_OUTSTANDING && FCF > 0) {
  let total_pv = 0;
  let fcf_year = FCF;
  let phase1_valid = true;

  // Phase 1: 고성장 구간 (1-5년)
  // FIX #2: phase1 루프 변수를 phase2와 분리
  for (let y = 1; y <= 5; y++) {
    fcf_year *= (1 + GROWTH_RATE_PHASE1);
    // FIX #9: 중간에 FCF가 음수가 될 경우 중단
    if (fcf_year < 0) {
      phase1_valid = false;
      dcf_signal = 'NEGATIVE_GROWTH_PATH';
      break;
    }
    total_pv += fcf_year / Math.pow(1 + DISCOUNT_RATE, y);
  }

  if (phase1_valid) {
    // FIX #2: Phase2는 Phase1 마지막 값에서 시작 (별도 변수)
    let fcf_phase2 = fcf_year;
    for (let y = 6; y <= PROJECTION_YEARS; y++) {
      // FIX #2: 선형보간 수식 수정 (y=6: PHASE1, y=10: PHASE2)
      const progress = (y - 5) / (PROJECTION_YEARS - 5);
      const blend_rate = GROWTH_RATE_PHASE1 * (1 - progress) + GROWTH_RATE_PHASE2 * progress;
      fcf_phase2 *= (1 + blend_rate);
      total_pv += fcf_phase2 / Math.pow(1 + DISCOUNT_RATE, y);
    }

    // FIX #3: fcf_phase2가 이미 10년차 값 → 한번만 성장 적용
    const terminal_value = fcf_phase2 * (1 + GROWTH_RATE_PHASE2) / (DISCOUNT_RATE - GROWTH_RATE_PHASE2);
    total_pv += terminal_value / Math.pow(1 + DISCOUNT_RATE, PROJECTION_YEARS);

    // FIX #17: 베타 연동 안전마진 동적 조정
    let safety_margin;
    if (d.beta && d.beta > 2.0)       safety_margin = 0.55; // 고변동성: 45% 마진
    else if (d.beta && d.beta > 1.5)  safety_margin = 0.60; // 중고변동성: 40% 마진
    else if (d.beta && d.beta > 1.0)  safety_margin = 0.65; // 중변동성: 35% 마진
    else                               safety_margin = 0.70; // 기본: 30% 마진 (버핏)

    dcf_intrinsic_value = (total_pv / SHARES_OUTSTANDING) * safety_margin;

    // FIX #19: current_price=0 무한대 방지
    if (d.current_price && d.current_price > 0) {
      dcf_signal = d.current_price < dcf_intrinsic_value * 0.8 ? 'UNDERVALUED'
        : d.current_price > dcf_intrinsic_value * 1.2 ? 'OVERVALUED' : 'FAIR';
    }
  }
}

// ================================================================
// [RULE-04] 종합 적정주가 (가중평균, 정규화 포함)
// ================================================================
const WEIGHTS = { PER: 0.30, PBR: 0.20, DCF: 0.50 };

const valid_prices = [
  per_fair_price ? { val: per_fair_price, weight: WEIGHTS.PER, model: 'PER' } : null,
  pbr_fair_price ? { val: pbr_fair_price, weight: WEIGHTS.PBR, model: 'PBR' } : null,
  dcf_intrinsic_value ? { val: dcf_intrinsic_value, weight: WEIGHTS.DCF, model: 'DCF' } : null
].filter(Boolean);

let composite_fair_price = null;
let total_weight = 0;

if (valid_prices.length > 0) {
  const weighted_sum = valid_prices.reduce((acc, p) => acc + p.val * p.weight, 0);
  total_weight = valid_prices.reduce((acc, p) => acc + p.weight, 0);
  composite_fair_price = weighted_sum / total_weight;  // 정규화된 가중평균
}

// ================================================================
// [RULE-05] 투자 등급
// ================================================================
const signals = [per_signal, pbr_signal, dcf_signal].filter(s => s !== 'INSUFFICIENT_DATA' && s !== 'INVALID_PARAMETERS' && s !== 'NEGATIVE_GROWTH_PATH');
const undervalued_count = signals.filter(s => s === 'UNDERVALUED').length;
const overvalued_count = signals.filter(s => s === 'OVERVALUED').length;

const GRADE_TABLE = {
  '3_0': { grade: 'STRONG_BUY',  label: '강력매수', color: '#00C851' },
  '2_0': { grade: 'BUY',         label: '매수',     color: '#7CB342' },
  '1_0': { grade: 'WEAK_BUY',   label: '약매수',   color: '#B2DFDB' },
  '1_1': { grade: 'HOLD',        label: '보유',     color: '#FFA726' },
  '0_0': { grade: 'HOLD',        label: '보유',     color: '#FFA726' },
  '0_1': { grade: 'WEAK_SELL',  label: '약매도',   color: '#EF9A9A' },
  '0_2': { grade: 'SELL',        label: '매도',     color: '#F44336' },
  '0_3': { grade: 'STRONG_SELL', label: '강력매도', color: '#B71C1C' }
};

const grade_key = `${undervalued_count}_${overvalued_count}`;
const investment_grade = GRADE_TABLE[grade_key] || { grade: 'NEUTRAL', label: '중립', color: '#9E9E9E' };

// FIX #19: current_price=0 상승여력 무한대 방지
const upside_potential = (composite_fair_price && d.current_price && d.current_price > 0)
  ? ((composite_fair_price - d.current_price) / d.current_price * 100).toFixed(2)
  : null;

// ================================================================
// FIX #18: 가중 데이터 품질 점수 (0 = 누락, 0값 정상 처리)
// ================================================================
const quality_fields = [
  { name: 'eps',                 value: d.eps,                 weight: 0.25 },
  { name: 'book_value_per_share',value: d.book_value_per_share,weight: 0.25 },
  { name: 'free_cash_flow',      value: d.free_cash_flow,      weight: 0.25 },
  { name: 'revenue',             value: d.revenue,             weight: 0.15 },
  { name: 'net_income',          value: d.net_income,          weight: 0.10 }
];
const data_quality_score = Math.round(
  quality_fields
    .filter(f => f.value !== null && f.value !== undefined)
    .reduce((sum, f) => sum + f.weight, 0) * 100
);

return [{
  json: {
    ...d,
    data_quality_score,
    models_available: valid_prices.map(p => p.model),
    valuation: {
      per: {
        trailing: per_trailing?.toFixed(2),
        forward: per_forward?.toFixed(2),
        signal: per_signal,
        fair_price: per_fair_price?.toFixed(2),
        benchmark: per_bench
      },
      pbr: {
        value: pbr?.toFixed(2),
        signal: pbr_signal,
        fair_price: pbr_fair_price?.toFixed(2),
        benchmark: pbr_bench
      },
      dcf: {
        intrinsic_value: dcf_intrinsic_value?.toFixed(2),
        signal: dcf_signal,
        growth_rate_used: pct(GROWTH_RATE_PHASE1),
        discount_rate: pct(DISCOUNT_RATE),
        terminal_growth: pct(GROWTH_RATE_PHASE2)
      },
      composite: {
        fair_price: composite_fair_price?.toFixed(2),
        current_price: d.current_price,
        upside_potential: upside_potential ? upside_potential + '%' : 'N/A',
        investment_grade: investment_grade.grade,
        grade_label: investment_grade.label,
        grade_color: investment_grade.color,
        models_used: valid_prices.length,
        models_list: valid_prices.map(p => p.model).join('+'),
        data_quality_score
      }
    },
    calculated_at: new Date().toISOString()
  }
}];

