// ================================================================
// LAYER 4 - NODE 4-4: Gemini + Claude 결과 통합
// FIX #13: 입력 순서 가정 제거 → 노드명으로 명시적 참조
// FIX #20: JSON 파싱 try-catch 추가
// ================================================================

// FIX #20: 안전한 JSON 파싱 헬퍼
const safeJsonParse = (text, nodeName) => {
  if (!text) return { _parse_error: `Empty response from ${nodeName}` };
  // LLM이 마크다운 코드블록으로 감쌀 경우 제거
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // JSON 파싱 실패 시 폴백: 원문 보존
    return { _parse_error: e.message, _raw_text: cleaned.substring(0, 200) };
  }
};

// FIX #13: 노드명 기반 명시적 참조 ($('노드명').first().json)
const gemini_raw = $('Gemini 분석').first().json;
const claude_raw = $('Claude 분석').first().json;
const base = $('패킷 구조화').first().json;

// Gemini 응답 파싱 (Gemini API 구조: candidates[0].content.parts[0].text)
const gemini_text = gemini_raw.candidates?.[0]?.content?.parts?.[0]?.text || '';
const gemini_parsed = safeJsonParse(gemini_text, 'Gemini');

// Claude 응답 파싱 (Anthropic API 구조: content[0].text)
const claude_text = claude_raw.content?.[0]?.text || '';
const claude_parsed = safeJsonParse(claude_text, 'Claude');

// LLM 실패 시 안전 기본값
const safe_claude = { risk_grade: 'MEDIUM', risk_score: 50, ...claude_parsed };
const safe_gemini = { time_horizon: '중기', bull_case: 'N/A', bear_case: 'N/A', ...gemini_parsed };

// 리스크 등급 반영 (VERY_HIGH일 때 투자등급 1단계 하향)
const combined_signal = safe_claude.risk_grade === 'VERY_HIGH'
  ? 'DOWNGRADE_' + base.payload.valuation.composite.investment_grade
  : base.payload.valuation.composite.investment_grade;

return [{
  json: {
    ...base.payload,
    llm_analysis: {
      qualitative: safe_gemini,
      risk: safe_claude,
      combined_signal,
      final_recommendation: {
        grade: base.payload.valuation.composite.investment_grade,
        label: base.payload.valuation.composite.grade_label,
        fair_price: base.payload.valuation.composite.fair_price,
        upside: base.payload.valuation.composite.upside_potential,
        risk_score: safe_claude.risk_score,
        risk_grade: safe_claude.risk_grade,
        time_horizon: safe_gemini.time_horizon,
        key_bullish: safe_gemini.bull_case,
        key_bearish: safe_gemini.bear_case,
        stop_loss: safe_claude.stop_loss_suggestion,
        position_size: safe_claude.position_size_suggestion,
        red_flags: safe_claude.red_flags,
        catalyst_events: safe_gemini.catalyst_events,
        models_used: base.payload.valuation.composite.models_list,
        data_quality_score: base.payload.data_quality_score
      },
      parse_status: {
        gemini_ok: !gemini_parsed._parse_error,
        claude_ok: !claude_parsed._parse_error
      },
      analyzed_at: new Date().toISOString()
    }
  }
}];

